import{z as n,x as i,o as r,c,q as E,j as s,D as l,d as e,s as d,S as A,b as o}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"链接与重定位","description":"","frontmatter":{"title":"链接与重定位","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/link-reloc.md","filePath":"cs/link-reloc.md","lastUpdated":1791413859000}'),B={name:"cs/link-reloc.md"};function p(m,a,C,h,f,D){const t=i("Mermaid");return r(),c("div",null,[a[2]||(a[2]=E('<h1 id="链接与重定位" tabindex="-1">链接与重定位 <a class="header-anchor" href="#链接与重定位" aria-label="Permalink to &quot;链接与重定位&quot;">​</a></h1><div class="epigraph"><p>汇编留下对符号的空洞；链接器把多个可重定位目标拼成一份地址空间，并按重定位项把空洞填成真正的位移或绝对地址。</p><footer>—— 据龙书第 7 章；System V ABI 与 ELF 规范整理</footer></div><p>上一课<a href="/cs/pic">位置无关代码</a>发出遵守调用约定的指令，其中 <code>call foo</code> 的目标往往还不是最终地址。本课不重写序言。缺口是：<strong>多份目标文件</strong>如何合成一个程序——符号解析与重定位。动态加载再下一课才把运行时绑进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>编译器按编译单元工作，不知道 <code>printf</code> 的最终虚址。目标文件提供：代码/数据节、符号表（定义与未定义引用）、重定位列表（偏移、类型、符号）。静态链接：解析未定义到某份 <code>.o</code> 或 <code>.a</code> 的定义，排布节，应用重定位。失败：未定义引用或重复定义。</p><p><a href="/cs/stored-program">存储程序</a>已说指令在内存；本课问地址何时钉死。可执行文件有入口点；共享库的地址可推迟。</p><h3 id="重定位不是「再编译」" tabindex="-1">重定位不是「再编译」 <a class="header-anchor" href="#重定位不是「再编译」" aria-label="Permalink to &quot;重定位不是「再编译」&quot;">​</a></h3><p>链接器不读源，不跑类型检查。它读节与记录。PC 相对跳转填的是差；绝对地址填的是虚址。ISA 立即数宽度不够则链接失败或要存根，选择课已碰立即数，这里是链接期诊断。</p><p><span class="marginnote">术语翻译：重定位项就是一张「待补洞清单」——每条记录「哪个文件、哪个偏移处有个洞、这个洞该按什么公式补」。链接器不读你的源代码，只逐条按这份清单把洞填成正确字节。</span></p><p><span class="marginnote">ELF 的 <code>R_X86_64_*</code> / <code>R_RISCV_*</code> 类型在 psABI 里。本课不枚举。Unix 链接器与 <code>ld</code> 的脚本控制节序，点名即可。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读入 <code>.o</code>。合并同类节。解析符号：强符号冲突报错，弱符号规则按文档。按重定位项：<code>S+A-P</code> 等公式写入指定字节。输出可执行或可再重定位的 <code>.so</code> 雏形。</p>',12)),(r(),s(A,null,{default:l(()=>[d(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22%E5%A4%9A%E4%B8%AA%20.o%22%5D%20--%3E%20SYM%5B%22%E8%A7%A3%E6%9E%90%E7%AC%A6%E5%8F%B7%22%5D%0A%20%20SYM%20--%3E%20LAY%5B%22%E6%8E%92%E5%B8%83%E8%8A%82%E5%9C%B0%E5%9D%80%22%5D%0A%20%20LAY%20--%3E%20REL%5B%22%E5%BA%94%E7%94%A8%E9%87%8D%E5%AE%9A%E4%BD%8D%22%5D%0A%20%20REL%20--%3E%20EXE%5B%22%E5%8F%AF%E6%89%A7%E8%A1%8C%E6%88%96%E5%85%B1%E4%BA%AB%E5%AF%B9%E8%B1%A1%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("p",null,[e("静态库是按需抽取的 "),o("code",null,".o"),e(" 包，解析时拉入。")],-1)),a[4]||(a[4]=o("h2",{id:"机制",tabindex:"-1"},[e("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=o("p",null,[e("ABI 的调用约定保证拉进来的 "),o("code",null,"foo"),e(" 能用当前的参数寄存器。链接不管类型：C 的弱类型可链上签名错误的定义，那是语言/链接器分工，类型课的检查过不了别的文件除非 LTO。本课点名：常规链接信任符号名。")],-1)),(r(),s(A,null,{default:l(()=>[d(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22S%EF%BC%9Afoo%20%E7%9A%84%E6%9C%80%E7%BB%88%E5%9C%B0%E5%9D%80%200x401100%22%5D%20--%3E%20CALC%5B%22%E5%A5%97%20PC%20%E7%9B%B8%E5%AF%B9%E5%85%AC%E5%BC%8F%20S%2BA-P%22%5D%0A%20%20A%5B%22A%EF%BC%9A%E5%8A%A0%E6%95%B0%20-4%EF%BC%88%E4%BD%8D%E7%A7%BB%E5%9F%BA%E5%87%86%E6%98%AF%20P%2B4%EF%BC%89%22%5D%20--%3E%20CALC%0A%20%20P%5B%22P%EF%BC%9A%E9%87%8D%E5%AE%9A%E4%BD%8D%E5%A4%84%E5%9C%B0%E5%9D%80%200x401050%22%5D%20--%3E%20CALC%0A%20%20CALC%20--%3E%20W%5B%22%E6%8A%8A%E5%B7%AE%E5%80%BC%200xAC%20%E5%86%99%E8%BF%9B%20call%20%E7%9A%84%E7%AB%8B%E5%8D%B3%E6%95%B0%E6%A7%BD%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=E('<p><span class="marginnote">数字实例：<code>call foo</code> 的 32 位位移槽位于 0x401050，foo 最终落在 0x401100，则 S+A-P = 0x401100 − 4 − 0x401050 = 0xAC（call 的相对位移以 P+4 为基准，故加数取 −4）。CPU 执行时拿「下一条指令地址（0x401050+4 = 0x401054）+ 0xAC = 0x401100」就跳到 foo——链接器填的正是这个相对差，不是绝对地址。</span></p><p><span class="marginnote">常见误区：初学者以为链接器会检查函数参数类型对不对。实际上静态链接只对符号名字，两个文件对同一函数的签名理解不一致也能链过，错误要等运行时才炸（除非开 LTO 把类型信息带进链接期）。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 <code>mmap</code> 加载、不写 PLT/GOT 的运行时跳板（下一课）。不处理内核模块特殊重定位。后课默认：静态链接产物地址已填好。动态链接把部分重定位推迟到加载或第一次调用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>链接 = 符号解析 + 节排布 + 重定位填写。</li><li>编译单元各自的空洞在此闭合。</li><li>不读源；类型错误可以漏到运行时若逃过前端。</li><li>出处：Aho et al., 龙书第 7 章；ELF 与 System V/RISC-V psABI。</li></ul>',6))])}const x=n(B,[["render",p]]);export{u as __pageData,x as default};
